#!/bin/bash

set -euo pipefail

COOKIEJAR="$HOME/.earthdata_cookies"
NETRC="$HOME/.netrc"

if [[ ! -f "$NETRC" ]]; then
    echo "ERROR: $NETRC not found"
    exit 1
fi

touch "$COOKIEJAR"
chmod 600 "$COOKIEJAR"

reauthenticate() {
    echo "Refreshing Earthdata session..."

    rm -f "$COOKIEJAR"
    touch "$COOKIEJAR"
    chmod 600 "$COOKIEJAR"

    curl -s \
         -n \
         -L \
         -c "$COOKIEJAR" \
         -b "$COOKIEJAR" \
         "https://urs.earthdata.nasa.gov" \
         >/dev/null
}

download_file() {

    local url="$1"
    local outfile="$2"

    echo "Downloading $outfile"

    http_code=$(
        curl \
            -s \
            -L \
            -n \
            --retry 5 \
            --retry-delay 10 \
            --retry-all-errors \
            -b "$COOKIEJAR" \
            -c "$COOKIEJAR" \
            -w "%{http_code}" \
            -o "$outfile" \
            "$url"
    )

    if [[ "$http_code" == "401" || "$http_code" == "403" ]]; then

        echo "Authentication expired (HTTP $http_code)"
        reauthenticate

        http_code=$(
            curl \
                -s \
                -L \
                -n \
		--retry 20 \
		--retry-delay 30 \
		--retry-all-errors \
		--connect-timeout 60 \
                -b "$COOKIEJAR" \
                -c "$COOKIEJAR" \
                -w "%{http_code}" \
                -o "$outfile" \
                "$url"
        )
    fi

    if [[ "$http_code" != "200" ]]; then
        echo "ERROR downloading $outfile (HTTP $http_code)"
        return 1
    fi

    echo "Finished $outfile"
}

while read -r url; do

    [[ -z "$url" ]] && continue

    file="${url##*/}"
    file="${file%%\?*}"

    download_file "$url" "$file"

done <<'EOF'
